import {extractReceipt} from './receipt-model.mjs';
import {categories,validData} from './model.mjs';
export function setupReceipts({getData,persist,onImported,toast}){
 const $=id=>document.getElementById(id);let file=null,url=null,controller=null,busy=false,run=0;
 $('receipt-category').replaceChildren(...categories.expense.map(c=>new Option(c,c)));$('receipt-category').value='その他';
 const status=(message,error=false)=>{$('receipt-status').textContent=message;$('receipt-status').classList.toggle('review-error',error);};
 $('receipt-open').onclick=()=>$('receipt-dialog').showModal();const stop=()=>controller?.abort();$('receipt-close').onclick=()=>{stop();$('receipt-dialog').close();};$('receipt-dialog').addEventListener('cancel',stop);$('receipt-cancel').onclick=stop;
 const uncheck=()=>{$('receipt-checked').checked=false;$('receipt-confirm').disabled=true;};
 for(const id of ['receipt-date','receipt-amount','receipt-note','receipt-category','receipt-source'])$(id).addEventListener('input',uncheck);
 $('receipt-checked').onchange=()=>{$('receipt-confirm').disabled=!$('receipt-checked').checked;};
 $('receipt-file').onchange=()=>{file=$('receipt-file').files[0]||null;run++;$('receipt-review').hidden=true;$('receipt-image-panel').hidden=true;uncheck();if(url){URL.revokeObjectURL(url);url=null;}$('receipt-read').disabled=true;if(!file)return;if(file.size>20*1024*1024){status('20MB以下の画像を選んでください。',true);file=null;return;}if(!/\.(png|jpe?g|webp)$/i.test(file.name)&&!/^image\/(png|jpeg|webp)$/.test(file.type)){status('PNG・JPEG・WebP形式の画像を選んでください。',true);file=null;return;}url=URL.createObjectURL(file);$('receipt-image').src=url;$('receipt-image-panel').hidden=false;$('receipt-read').disabled=false;status('画像を選択しました。「写真をOCRで読み取る」を押してください。');};
 function setBusy(value){busy=value;$('receipt-file').disabled=value;$('receipt-read').disabled=value||!file;$('receipt-cancel').hidden=!value;$('receipt-progress').hidden=!value;}
 $('receipt-read').onclick=async()=>{if(busy||!file)return;const thisRun=++run;controller=new AbortController();setBusy(true);uncheck();$('receipt-review').hidden=true;
 try{const {readDocument}=await import('./pdf-reader.mjs');const pages=await readDocument(file,{mode:'ocr'},(message,value)=>{if(thisRun!==run)return;status(message);if(value===null)$('receipt-progress').removeAttribute('value');else $('receipt-progress').value=value;},controller.signal);if(thisRun!==run)return;const text=pages.map(p=>p.text).join('\n'),result=extractReceipt(text);$('receipt-text').textContent=text||'文字を認識できませんでした。';$('receipt-date').value=result.date;$('receipt-amount').value=result.amount||'';$('receipt-note').value=result.note;$('receipt-source').value='';$('receipt-category').value='その他';$('receipt-amounts').replaceChildren(new Option('別の候補を選ぶ（または金額を手入力）',''),...result.amounts.map(a=>new Option(`${a.value.toLocaleString('ja-JP')}円 — ${a.label}`,String(a.value))));$('receipt-review').hidden=false;status(result.warnings.length?result.warnings.join(' '):'読み取りが完了しました。写真と見比べて確認してください。',result.warnings.length>0);if(!text.trim())status('文字を認識できませんでした。明るさ・向き・解像度を確認するか、結果欄に手入力してください。',true);
 }catch(e){if(thisRun===run)status(e.name==='AbortError'?'読み取りを中止しました。':e.message||'読み取りに失敗しました。画像を確認してください。',e.name!=='AbortError');}
 finally{if(thisRun===run){setBusy(false);controller=null;}}
 };
 $('receipt-amounts').onchange=()=>{if($('receipt-amounts').value){$('receipt-amount').value=$('receipt-amounts').value;uncheck();}};
 $('receipt-review').onsubmit=e=>{e.preventDefault();if(!$('receipt-checked').checked){toast('写真と照合してチェックしてください。');return;}const entry={id:crypto.randomUUID(),date:$('receipt-date').value,amount:Number($('receipt-amount').value),note:$('receipt-note').value.trim(),category:$('receipt-category').value,source:$('receipt-source').value.trim(),type:'expense'};const next={...getData(),entries:[...getData().entries,entry]};if(!validData(next)){toast('日付・金額を確認してください。');return;}if(persist(next)){$('receipt-dialog').close();$('receipt-review').hidden=true;uncheck();onImported(entry.date);toast('レシートを支出として登録しました');}};
 $('receipt-dialog').addEventListener('close',()=>{stop();if(url){URL.revokeObjectURL(url);url=null;}$('receipt-image').removeAttribute('src');$('receipt-image-panel').hidden=true;$('receipt-file').value='';file=null;$('receipt-read').disabled=true;$('receipt-review').hidden=true;});
}
